mapper.select:
SELECT COUNT(1) FROM operation_log

    AND action = #{action}
    AND user_id = #{userId}

SELECT o.id, o.user_id, o.action, o.target, o.detail, o.created_at,
       u.name AS user_name
FROM operation_log o
LEFT JOIN sys_user u ON u.id = o.user_id

    AND o.action = #{action}
    AND o.user_id = #{userId}

ORDER BY o.created_at DESC, o.id DESC
LIMIT #{offset}, #{limit}
